import sys

def merge_the_tools(s, k):
    n = len(s)
    for i in range(0, n, k):
        substring = s[i:i + k]
        seen = set()
        result = []
        for char in substring:
            if char not in seen:
                seen.add(char)
                result.append(char)
        print(''.join(result))

if __name__ == '__main__':
    s = sys.stdin.readline().strip()
    k_line = sys.stdin.readline().strip()
    if k_line:
        k = int(k_line)
        merge_the_tools(s, k)
